using Dapper; using Sigov.Application.Agro.FeirasMercados; using Sigov.Application.Common; using Sigov.Infrastructure.Persistence.Dapper;
namespace Sigov.Infrastructure.Agro.Repositories;
public sealed class AgroFeirasRepository:IAgroFeirasRepository{private readonly DapperContext _c; public AgroFeirasRepository(DapperContext c)=>_c=c; public async Task<PagedResult<AgroFeiraResponse>> ListarFeirasAsync(long t,long e,int p,int ps,CancellationToken ct){using var cn=_c.CreateConnection(); var rows=await cn.QueryAsync<AgroFeiraResponse>(new CommandDefinition("select id,tenant_id TenantId,entidade_id EntidadeId,codigo,nome,local,situacao,latitude,longitude,geojson::text GeoJson,ativo from sigov.agro_feira where tenant_id=@t and entidade_id=@e and is_deleted=false order by created_at desc limit @ps offset @o",new{t,e,ps,o=(p-1)*ps},cancellationToken:ct)); return new(rows.AsList(),p,ps,rows.Count());} public async Task<AgroFeiraResponse?> ObterFeiraAsync(long t,long e,long id,CancellationToken ct){using var cn=_c.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<AgroFeiraResponse>(new CommandDefinition("select id,tenant_id TenantId,entidade_id EntidadeId,codigo,nome,local,situacao,latitude,longitude,geojson::text GeoJson,ativo from sigov.agro_feira where tenant_id=@t and entidade_id=@e and id=@id and is_deleted=false",new{t,e,id},cancellationToken:ct));} public async Task<long> CriarFeiraAsync(long t,long e,long? u,AgroFeiraCreateRequest r,CancellationToken ct){using var cn=_c.CreateConnection(); return await cn.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.agro_feira(tenant_id,entidade_id,codigo,nome,local,dia_semana,horario,latitude,longitude,geojson,situacao,observacao,created_by) values(@t,@e,@Codigo,@Nome,@Local,@DiaSemana,@Horario,@Latitude,@Longitude,@GeoJson::jsonb,@Situacao,@Observacao,@u) returning id",new{t,e,u,r.Codigo,r.Nome,r.Local,r.DiaSemana,r.Horario,r.Latitude,r.Longitude,r.GeoJson,r.Situacao,r.Observacao},cancellationToken:ct));} public async Task AtualizarFeiraAsync(long t,long e,long id,long? u,AgroFeiraCreateRequest r,CancellationToken ct){using var cn=_c.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_feira set codigo=@Codigo,nome=@Nome,local=@Local,dia_semana=@DiaSemana,horario=@Horario,latitude=@Latitude,longitude=@Longitude,geojson=@GeoJson::jsonb,situacao=@Situacao,observacao=@Observacao,updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and id=@id",new{t,e,id,u,r.Codigo,r.Nome,r.Local,r.DiaSemana,r.Horario,r.Latitude,r.Longitude,r.GeoJson,r.Situacao,r.Observacao},cancellationToken:ct));} public async Task ExcluirFeiraAsync(long t,long e,long id,long? u,CancellationToken ct){using var cn=_c.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_feira set is_deleted=true,ativo=false,deleted_at=now(),deleted_by=@u where tenant_id=@t and entidade_id=@e and id=@id",new{t,e,id,u},cancellationToken:ct));} public async Task<PagedResult<AgroFeiranteResponse>> ListarFeirantesAsync(long t,long e,int p,int ps,CancellationToken ct){using var cn=_c.CreateConnection(); var rows=await cn.QueryAsync<AgroFeiranteResponse>(new CommandDefinition("select id,tenant_id TenantId,entidade_id EntidadeId,feira_id FeiraId,numero_cadastro NumeroCadastro,tipo_feirante TipoFeirante,autorizado,validade_autorizacao ValidadeAutorizacao,situacao,ativo from sigov.agro_feirante where tenant_id=@t and entidade_id=@e and is_deleted=false order by created_at desc limit @ps offset @o",new{t,e,ps,o=(p-1)*ps},cancellationToken:ct)); return new(rows.AsList(),p,ps,rows.Count());} public async Task<long> CriarFeiranteAsync(long t,long e,long feiraId,long? u,AgroFeiranteCreateRequest r,CancellationToken ct){using var cn=_c.CreateConnection(); return await cn.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.agro_feirante(tenant_id,entidade_id,feira_id,produtor_id,pessoa_id,numero_cadastro,tipo_feirante,produtos_json,autorizado,validade_autorizacao,situacao,observacao,created_by) values(@t,@e,@feiraId,@ProdutorId,@PessoaId,@NumeroCadastro,@TipoFeirante,coalesce(@ProdutosJson::jsonb,'[]'::jsonb),@Autorizado,@ValidadeAutorizacao,@Situacao,@Observacao,@u) returning id",new{t,e,feiraId,u,r.ProdutorId,r.PessoaId,r.NumeroCadastro,r.TipoFeirante,r.ProdutosJson,r.Autorizado,r.ValidadeAutorizacao,r.Situacao,r.Observacao},cancellationToken:ct));} public async Task AtualizarFeiranteStatusAsync(long t,long e,long id,string s,bool aut,long? u,CancellationToken ct){using var cn=_c.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_feirante set situacao=@s,autorizado=@aut,updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and id=@id",new{t,e,id,s,aut,u},cancellationToken:ct));} public async Task<PagedResult<AgroBancaFeiraResponse>> ListarBancasAsync(long t,long e,long feiraId,CancellationToken ct){using var cn=_c.CreateConnection(); var rows=await cn.QueryAsync<AgroBancaFeiraResponse>(new CommandDefinition("select id,tenant_id TenantId,entidade_id EntidadeId,feira_id FeiraId,feirante_id FeiranteId,numero_banca NumeroBanca,status,ativo from sigov.agro_banca_feira where tenant_id=@t and entidade_id=@e and feira_id=@feiraId and is_deleted=false",new{t,e,feiraId},cancellationToken:ct)); return new(rows.AsList(),1,100,rows.Count());} public async Task<long> CriarBancaAsync(long t,long e,long feiraId,long? u,AgroBancaFeiraCreateRequest r,CancellationToken ct){using var cn=_c.CreateConnection(); return await cn.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.agro_banca_feira(tenant_id,entidade_id,feira_id,feirante_id,numero_banca,localizacao_descricao,tipo_banca,status,created_by) values(@t,@e,@feiraId,@FeiranteId,@NumeroBanca,@LocalizacaoDescricao,@TipoBanca,@Status,@u) returning id",new{t,e,feiraId,u,r.FeiranteId,r.NumeroBanca,r.LocalizacaoDescricao,r.TipoBanca,r.Status},cancellationToken:ct));}}
